+
+func TestSliceConsumesRemainingPositionalArgs(t *testing.T) {
+	var cli struct {
+		Remainder []string `arg:""`
+	}
+	p := mustNew(t, &cli)
+	_, err := p.Parse([]string{"--", "ls", "-lart"})
+	require.NoError(t, err)
+	require.Equal(t, []string{"ls", "-lart"}, cli.Remainder)
+}
